(()=>{'use strict';const grid=document.getElementById('motionGrid'),videos=[];
for(const item of window.ActionVideoLibrary){let index=0;const card=document.createElement('article');card.className='motion-card';card.innerHTML=`<video muted playsinline loop controls preload="none" aria-label="${item.title}"></video><div class="motion-copy"><h2>${item.title}</h2><p>${item.focus}</p><button class="secondary-button play">▶ İzle</button> <button class="secondary-button variant">Diğer örnek</button><p class="credit"></p><p class="video-status" role="status"></p></div>`;grid.append(card);const video=card.querySelector('video'),button=card.querySelector('.play');videos.push(video);
const load=()=>{video.pause();const v=item.variants[index];video.src=`./assets/actions/videos/${v.file}`;video.poster=`./assets/actions/videos/${v.poster}`;card.querySelector('.credit').innerHTML=`Örnek ${index+1} / ${item.variants.length} · 6,5 saniye · ${v.credit} / <a href="${v.source}" target="_blank" rel="noopener">Pexels</a>`;card.querySelector('.video-status').textContent='';button.textContent='▶ İzle';};load();card.querySelector('.variant').onclick=()=>{index=(index+1)%item.variants.length;load();};
button.onclick=async()=>{if(video.paused){video.currentTime=0;try{await video.play();}catch{card.querySelector('.video-status').textContent='Video açılamadı. Sayfayı yenileyip tekrar deneyin.';}}else video.pause();};video.addEventListener('play',()=>{videos.forEach(other=>{if(other!==video)other.pause();});button.textContent='Duraklat';});video.addEventListener('pause',()=>button.textContent='▶ İzle');video.addEventListener('error',()=>{card.querySelector('.video-status').textContent='Video dosyası yüklenemedi.';});new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)video.pause();}).observe(card);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)videos.forEach(v=>v.pause());});window.addEventListener('pagehide',()=>videos.forEach(v=>v.pause()));document.getElementById('motionBack').onclick=()=>{if(parent!==window)parent.postMessage({type:'action-preview-menu'},location.origin);else location.href='./';};})();
